'use client';

import React from 'react';
import ReactDOM from 'react-dom/client';
// import './index.css';
import App from './App';

export class Solution {
	divHost: HTMLDivElement;
	constructor(id: string) {
		this.divHost = document.getElementById(id) as HTMLDivElement;
		const div = document.createElement('div');
		div.style.width = '100%';
		div.style.height = '100%';
		div.style.position = 'relative';
		// div.style.overflow = 'hidden';
		this.divHost.appendChild(div);

		const root = ReactDOM.createRoot(div);

		root.render(
			// <React.StrictMode>
			// <HelleApp /> syntax sugar
			React.createElement(App, {})
			// </React.StrictMode>
		);
	}
	destroy() {
		while (this.divHost.lastElementChild) {
			this.divHost.removeChild(this.divHost.lastElementChild);
		}
	}
}
