import React, { useState } from 'react';

import { Button } from 'antd';
import { motion } from 'framer-motion';

import styles from './ControlPanel.module.css';

export const LEFT_CONTROL_PANEL_ANIMATION_CONFIG = {
	open: {
		transition: {
			type: 'spring',
			bounce: 0,
			duration: 0.6,
		},
		x: 0,
	},
	closed: {
		transition: {
			type: 'spring',
			bounce: 0,
			duration: 0.6,
		},
		x: '-200px',
	},
};

const ControlPanel = ({}) => {
	let controlPaneOpen = true;
	const [controlPaneIsOpen, setControlPaneIsOpen] = useState(controlPaneOpen);
	const togglePanel = () => {
		setControlPaneIsOpen(!controlPaneIsOpen);
	};

	return (
		<motion.div animate={controlPaneIsOpen ? 'open' : 'closed'} variants={LEFT_CONTROL_PANEL_ANIMATION_CONFIG} className={`${styles.draggableContainer}`}>
			<Button
				className={controlPaneIsOpen ? styles.layersButtonExpanded : styles.layersButton}
				// icon={<img src={downIcon} className={controlPaneIsOpen ? styles.layersButtonIconOpen : styles.layersButtonIconClose} alt="control panel icon" />}
				onClick={togglePanel}
			/>
			<motion.div
			// className={hideControlPanelHeader ? styles.fullContainer : styles.container}>
			// 	{ternary(!hideControlPanelHeader, !defaultActiveTab.includes('Optimizer') ? <ControlPanelHeader geoid={geoid} /> : <OptimizerPanelHeader />, null)}
			>
				content
				{/* // {renderControlPanel()} */}
			</motion.div>
			{/* <CreateZoneModal /> */}
		</motion.div>
	);
};
export default ControlPanel;
