import { useEffect, useState, useRef } from 'react';

import { Button } from 'antd';
import { MenuOutlined, CloseOutlined } from '@ant-design/icons';

import { AppHypercube3d } from '../../utils/AppHypercube3d';
import ControlPanel from './ControlPanel';

import style from './styles.module.css';

type AppInstance = ReturnType<typeof AppHypercube3d.init>;

const Hypercube = () => {
	const id = 'hypercubeDiv';

	const hasInitialized = useRef<Awaited<AppInstance> | undefined>(undefined);

	const [open, setOpen] = useState(false);

	const showDrawer = () => {
		setOpen(true);
	};

	const onClose = () => {
		setOpen(false);
	};

	useEffect(() => {
		if (hasInitialized.current !== undefined) return;

		const init = async () => {
			hasInitialized.current = await AppHypercube3d.init(id);
		};

		init();

		return () => {
			if (hasInitialized.current && typeof hasInitialized.current?.destroy === 'function') {
				hasInitialized.current.destroy();
				console.warn('🧹 Destroyed Hypercube instance');
			}
		};
	}, []);

	return (
		<>
			<div className={`sliding-panel-wrapper ${open ? 'open' : ''}`}>
				{/* <div className={style.sidePanel}>
					<div className={style.panelContent}>
						<Button icon={<CloseOutlined />} onClick={() => setOpen(false)} />
						<h3>패널 내용</h3>
						<p>이곳에 원하는 컴포넌트나 내용을 넣으세요.</p>
					</div>
				</div>
				<div className="panel-handle" onClick={() => setOpen(true)}>
					<MenuOutlined />
				</div> */}

				<ControlPanel></ControlPanel>
			</div>

			<div className={style.hypercubeDivWrapper}>
				<div className={style.hypercubeDiv} id={id}></div>;
			</div>
		</>
	);
};

export default Hypercube;
